def solve(n, edges):
    class Graph:
        def __init__(self, n):
            self.adj = [[] for _ in range(n)]

        def add_edge(self, u, v):
            self.adj[u].append(v)
            self.adj[v].append(u)

        def dfs(self, node, visited):
            if visited[node]:
                return
            visited[node] = True
            for neighbor in self.adj[node]:
                if not visited[neighbor]:
                    self.dfs(neighbor, visited)

        def count_components(self):
            visited = [False] * n
            count = 0
            for i in range(n):
                if not visited[i]:
                    self.dfs(i, visited)
                    count += 1
            return count

    graph = Graph(n)
    for u, v in edges:
        graph.add_edge(u, v)
    return graph.count_components()
