            visited = [False] * n
            count = 0
            for i in range(n):
                if not visited[i]:
                    count += 1
                    self._dfs(i, visited)
            return count

        def _dfs(self, node, visited):
            visited[node] = True
            for neighbor in self.adj[node]:
                if not visited[neighbor]:
                    self._dfs(neighbor, visited)

    graph = Graph(n)
    for u, v in edges:
        graph.add_edge(u, v)
    return graph.count_components()
