    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build the graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    import heapq
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if u == t:
            return current_dist
        if current_dist > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    return -1
