    # Since weights can be zero, but no negative, we can use BFS for shortest path in terms of number of edges
    # But since weights are not uniform, we need to use Dijkstra or Bellman-Ford

    # Use Bellman-Ford to find the shortest path from s to t
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    for i in range(n):
