    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # If start and end are the same, return 0
    if s == t:
        return 0

    # Bellman-Ford to detect negative cycles and find shortest path
    # We will use a modified Bellman-Ford to find shortest path from s to t
    # Since weights are non-negative, we can use Dijkstra's algorithm for better performance
    # However, for the sake of handling possible negative weights (even though problem says 0 <= w <= 100), we use Bellman-Ford

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative cycles that are reachable from s
    # If there is a negative cycle on the path to t, then it's not bounded
    # Perform one more relaxation to detect negative cycles
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                # If t is reachable from u, then there is a negative cycle on the path to t
                if v == t:
                    return -1
                # Also check if t is reachable from v through any path
                # We check if there's a path from v to t after this relaxation
                # Simulate BFS to check reachability from v to t
                # Since the graph is directed, we'll do BFS from v
                visited = set()
                queue = deque([v])
                visited.add(v)
                while queue:
                    curr = queue.popleft()
                    for nei, _ in graph[curr]:
                        if nei not in visited:
                            visited.add(nei)
                            queue.append(nei)
                            if nei == t:
                                return -1
    return dist[t] if dist[t] != float('inf') else -1
