def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with Dijkstra's algorithm to find shortest path
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    queue = deque()
    queue.append(s)

    while queue:
        u = queue.popleft()
        visited[u] = True
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
