    from collections import defaultdict

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    def bfs(start, end):
        if start == end:
            return 0
        visited = set()
        queue = [(start, 0)]
        visited.add(start)
        while queue:
            node, dist = queue.pop(0)
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    if neighbor == end:
                        return dist + weight
                    queue.append((neighbor, dist + weight))
        return -1

    return bfs(s, t)
