    count = 0

    def dfs(u):
        stack = [u]
        visited[u] = True
        while stack:
            node = stack.pop()
            for v in range(n):
                if not visited[v] and any([u == a or u == b for a, b in edges if (a == v or b == v)]):
                    visited[v] = True
                    stack.append(v)

    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1

    return count
```

