def solve(n, edges):
    from collections import defaultdict

    def build_graph():
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def dfs(node, visited):
        stack = [node]
        visited.add(node)
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    graph = build_graph()
    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            dfs(i, visited)
            components += 1

    return components
