    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    for u, v in edges:
        union(u, v)

    root_count = set()
    for i in range(n):
        root_count.add(find(i))

    return len(root_count)
