from collections import defaultdict, deque

def solve(n, edges):
    if n == 0:
        return 0

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = 0

    for node in range(n):
        if not visited[node]:
            components += 1
            # BFS to mark all nodes in this component
            queue = deque([node])
            visited[node] = True
            while queue:
                current = queue.popleft()
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

    return components
