def solve(n, edges):
    from collections import deque

    if n == 0:
        return -1

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0

    # Use deque for 0-1 BFS
    dq = deque()
    dq.append(0)

    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if w == 0:
                    dq.appendleft(v)
                else:
                    dq.append(v)

    if dist[n-1] == INF:
        return -1
    return dist[n-1]
